window.QUIZ = (window.QUIZ || []).concat([
  { id: "6-001", ch: 6, sec: "6.1", page: 107, type: "recall", level: 2,
    q: "For corn in central Nebraska the book splits about 26 in of seasonal ET by source. Which split matches?",
    opts: ["About 4 in from rain, 12 in from stored soil water, and 10 in from irrigation","About 12 in from growing season rain, 4 in from stored soil water, and 10 in from net irrigation","About 10 in from rain, 4 in from stored soil water, and 12 in from irrigation","About 6 in from rain, 6 in from stored soil water, and 14 in from irrigation"], a: 1,
    why: "The book gives 12 in from growing season rainfall, 4 in from stored soil water, and the balance of 10 in from net irrigation. Good managers try to maximize the use of precipitation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-002", ch: 6, sec: "6.1", page: 107, type: "recall", level: 1,
    q: "Irrigation scheduling includes determining",
    opts: ["which irrigation system to buy","how often to apply water and how much water to apply","the water right priority date","the pump size and pipe diameter"], a: 1,
    why: "Scheduling is about timing and amount. System selection and pump sizing are design questions covered in other chapters.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-003", ch: 6, sec: "6.1", page: 107, type: "recall", level: 1,
    q: "Which are the three general approaches to scheduling irrigation listed in Chapter 6?",
    opts: ["Keep soil water within limits, use plant status indicators, or follow a calendar or fixed schedule","Use ET, rainfall, and runoff","Use tensiometers, neutron probes, and TDR","Irrigate at planting, flowering, and grain fill"], a: 0,
    why: "The three philosophies are soil water maintenance, plant status indicators, and fixed schedules. Tensiometers and TDR are tools within the soil water approach.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-004", ch: 6, sec: "6.1", page: 108, type: "recall", level: 2,
    q: "Fixed (calendar) irrigation schedules are often associated with",
    opts: ["drip systems with soil water sensors","center pivots with remote control","irrigation water supply districts that cannot deliver water on demand","turf systems with ET controllers"], a: 2,
    why: "The book links fixed schedules to districts that lack flexibility to deliver on demand. Automated systems can respond to soil water or ET instead.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-005", ch: 6, sec: "6.2", page: 108, type: "recall", level: 1,
    q: "What is the critical fraction remaining (frc)?",
    opts: ["The minimum fraction of available water that should remain to avoid stress and yield loss","The fraction of available water used each day","The fraction of the root zone below the sensor","The fraction of the field adequately irrigated"], a: 0,
    why: "frc is the lowest fraction of available soil water that keeps the crop at maximum yield. It is tied to fdc by fdc = 1 − frc.",
    eq: "6.1", calc: "eq-6.1", fig: null, table: null },
  { id: "6-006", ch: 6, sec: "6.2", page: 108, type: "recall", level: 2,
    q: "According to Doorenbos and Kassam (1979), the maximum allowable fraction depleted (fdc) ranges over what values?",
    opts: ["0.18 to 0.88","0.05 to 0.50","0.30 to 0.60","0.50 to 1.00"], a: 0,
    why: "fdc ranges from 0.18 to 0.88 depending on crop sensitivity and the day's maximum ET. These are the extreme corners of Table 6.1.",
    eq: null, calc: null, fig: null, table: "6.1" },
  { id: "6-007", ch: 6, sec: "6.2", page: 109, type: "recall", level: 1,
    q: "What fdc does the book suggest as a common average value when better data are not available?",
    opts: ["0.50","0.25","0.35","0.65"], a: 0,
    why: "A common level of fdc is 0.50. Use crop and ET specific values from Table 6.1 when available. 0.35 is the basis of the tension thresholds in Table 6.6.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-008", ch: 6, sec: "6.2", page: 109, type: "recall", level: 2,
    q: "Which list matches the possible management objectives for scheduling given in the book?",
    opts: ["Maximum ET, maximum runoff, and maximum drainage","Minimum pumping, minimum labor, and maximum pressure","Maximum yield, maximum economic return, functional value, aesthetic value, and maintaining plant life","Maximum root depth and maximum leaf area only"], a: 2,
    why: "The objective must be defined first. For crops it may be yield or profit, while for an athletic field it is function and for landscapes appearance or just keeping plants alive.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-009", ch: 6, sec: "6.3", page: 109, type: "recall", level: 1,
    q: "Allowable depletion (AD) is",
    opts: ["the depth applied per irrigation","the total water the root zone can hold between field capacity and wilting point","the water remaining at the time of irrigation","the amount of available water that can be removed from the root zone before plants undergo moisture stress"], a: 3,
    why: "AD = fdc × TAW and is a depth of water. The total held between FC and WP is TAW, and the water that must remain is MB.",
    eq: "6.4", calc: "eq-6.2-6.5", fig: null, table: null },
  { id: "6-010", ch: 6, sec: "6.3", page: 109, type: "recall", level: 1,
    q: "How are minimum balance (MB), TAW, and AD related?",
    opts: ["MB = AD − TAW","MB = TAW + AD","MB = AD ÷ TAW","MB = TAW − AD"], a: 3,
    why: "MB = frc × TAW and AD = fdc × TAW, and since frc + fdc = 1, MB = TAW − AD, or TAW = MB + AD.",
    eq: "6.5", calc: "eq-6.2-6.5", fig: null, table: null },
  { id: "6-011", ch: 6, sec: "6.3.1", page: 110, type: "recall", level: 1,
    q: "What minimum root depth is normally assumed for seedlings?",
    opts: ["24 in","1 to 2 in","12 to 18 in","4 to 6 in"], a: 3,
    why: "The book uses 4 to 6 in for RdMIN. An error here has very little effect on the soil water balance.",
    eq: "6.6", calc: "eq-6.6-6.7", fig: null, table: null },
  { id: "6-012", ch: 6, sec: "6.3.1", page: 110, type: "recall", level: 2,
    q: "How does the maximum effective root depth used for scheduling compare with the deepest roots found?",
    opts: ["It is the same as the deepest root","It is always deeper, to include capillary rise","It is usually less, the depth with enough rooting density to extract available water","It is the depth of the plow layer"], a: 2,
    why: "Some roots go deeper than the effective depth, but scheduling uses the profile with enough root density to extract water. Values in Table 6.2 should be adjusted for local soils and climate.",
    eq: null, calc: null, fig: null, table: "6.2" },
  { id: "6-013", ch: 6, sec: "6.3.1", page: 112, type: "recall", level: 2,
    q: "Even when crops root deeper than 3 ft by midseason, what root zone depth do many managers use until late in the season?",
    opts: ["1 ft","3 ft","2 ft","5 ft"], a: 1,
    why: "To be on the safe side, many managers use a 3-ft root zone until late in the season and then let the crop extract from the whole profile as maturity approaches.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-014", ch: 6, sec: "6.3.1", page: 111, type: "recall", level: 1,
    q: "What does the 4-3-2-1 rule describe?",
    opts: ["The ratio of root depth to crop height","The number of irrigations at 4 growth stages","Inches applied in the first 4 weeks","40%, 30%, 20%, and 10% of water extracted from successive quarters of the root zone, top down"], a: 3,
    why: "About 40% of the water comes from the top 25% of the root zone, 30% from the next quarter, then 20% and 10%. It applies when the root zone is refilled after each irrigation.",
    eq: null, calc: "extraction-4321", fig: "6.4", table: null },
  { id: "6-015", ch: 6, sec: "6.4", page: 113, type: "recall", level: 1,
    q: "What is the latest date (LD) in irrigation scheduling?",
    opts: ["The day the soil reaches field capacity","The last day of the irrigation season","The last day to irrigate before the deficit exceeds allowable depletion","The last day rain is forecast"], a: 2,
    why: "LD = (AD − SWD) / ETf. Irrigating on or before LD avoids plant water stress.",
    eq: "6.10", calc: "eq-6.10-6.11", fig: null, table: null },
  { id: "6-016", ch: 6, sec: "6.4", page: 115, type: "recall", level: 1,
    q: "What is the rainfall allowance (ra)?",
    opts: ["Room left in the soil profile to store rain that might fall right after an irrigation","The total rain expected for the season","The rain that runs off the field","The minimum rain needed to skip an irrigation"], a: 0,
    why: "In humid and semihumid regions it is good management to leave room for rain. ra is added in the earliest date equation, ED = (ra + dep − SWD) / ETf.",
    eq: "6.16", calc: "eq-6.16-6.17", fig: null, table: null },
  { id: "6-017", ch: 6, sec: "6.4.1", page: 116, type: "recall", level: 1,
    q: "In the checkbook equation SWDi = SWDi-1 + ETi-1 − dei-1 − Pei-1 − Ufi-1, what is Uf?",
    opts: ["Uniformity factor of the system","Unused fertilizer","Upward flow of groundwater from a shallow water table","Underflow to deep percolation"], a: 2,
    why: "Uf is capillary upward flow into the root zone from a shallow water table. It is a deposit, like effective rain and irrigation.",
    eq: "6.18", calc: "eq-6.18-6.25", fig: null, table: null },
  { id: "6-018", ch: 6, sec: "6.4.1", page: 117, type: "recall", level: 2,
    q: "How can the starting SWD or AW for checkbook accounting be set?",
    opts: ["Start at half of TAW in all cases","Assume the soil is at wilting point on the first day","Use the AD value as the starting deficit","Measure soil water, or start after a wet period or thorough irrigation when the soil is near field capacity"], a: 3,
    why: "The checkbook needs a starting value. Measure it with a method from Chapter 2, or start right after the profile is refilled so SWD is near zero.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-019", ch: 6, sec: "6.4.1", page: 117, type: "recall", level: 2,
    q: "How close to the bottom of the root zone must a water table be to supply a substantial fraction of ET?",
    opts: ["Within about 20 ft","Within about 10 ft","Within about 3 ft","Only at the root zone bottom itself"], a: 2,
    why: "Water tables within 3 ft of the root zone bottom can provide a substantial share of ET, even with saline water if the crop is fairly salt tolerant.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-020", ch: 6, sec: "6.4.1", page: 119, type: "recall", level: 2,
    q: "What is programmed soil moisture depletion (Fischbach and Somerhalder, 1973)?",
    opts: ["Irrigating to keep the soil at field capacity all season","Applications that replace only part of ET so the soil reservoir drains to low but safe levels late in the season","Letting the soil reach wilting point before each irrigation","Depleting the soil only in the first month"], a: 1,
    why: "By design, late season applications replace a fraction of ET, leaving room to store off-season precipitation. Figure 6.12 shows the gradual drawdown to plant maturity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-021", ch: 6, sec: "6.4.2", page: 119, type: "recall", level: 2,
    q: "Now that weather station networks give real time ET, what does the book call the biggest problem in checkbook scheduling?",
    opts: ["Finding ET data","Estimating effective irrigation depths, so water measurement is key","Computing the daily balance","Knowing the crop type"], a: 1,
    why: "Lack of real time ET was the old limitation. Today the hard part is knowing the effective depth, which needs measured water and the Chapter 5 methods.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-022", ch: 6, sec: "6.4.3", page: 120, type: "recall", level: 1,
    q: "For a 3-ft root zone sampled at 1-ft intervals, at what depths would sensors typically be placed?",
    opts: ["6, 18, and 30 in","12, 24, and 36 in","3, 6, and 9 in","18 in only"], a: 0,
    why: "Each sensor sits in the middle of the 1-ft layer it represents: 6 in for 0 to 12, 18 in for 12 to 24, and 30 in for 24 to 36 in.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-023", ch: 6, sec: "6.4.3", page: 121, type: "recall", level: 2,
    q: "What is needed to convert a soil water tension reading into water content or SWD?",
    opts: ["The crop coefficient","A neutron probe calibration","A soil water release curve for that soil","The bulk density only"], a: 2,
    why: "Tensiometers, granular matrix sensors and resistance blocks read potential. A release curve, a local calibration available from universities or NRCS, converts it to water content. Table 6.5 is an example.",
    eq: null, calc: null, fig: null, table: "6.5" },
  { id: "6-024", ch: 6, sec: "6.4.3", page: 121, type: "recall", level: 2,
    q: "Threshold soil water tensions from manufacturers are usually based on sensing where?",
    opts: ["Near the vertical center of the root zone","At the soil surface","At the bottom of the root zone","Just below the root zone"], a: 0,
    why: "Threshold guidelines usually assume a sensor near the vertical center of the root zone, as in Table 6.6.",
    eq: null, calc: null, fig: null, table: "6.6" },
  { id: "6-025", ch: 6, sec: "6.4.3", page: 122, type: "recall", level: 1,
    q: "What minimum number of locations should be sampled in a large irrigated area with relatively uniform soils and slopes?",
    opts: ["4","1","2","10"], a: 0,
    why: "The book says a minimum of four locations. Stress-prone areas can be added if they are a significant share of the area.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-026", ch: 6, sec: "6.4.3", page: 122, type: "recall", level: 3,
    q: "How is the observed field capacity (FCobs) for a sensor determined?",
    opts: ["From the soil survey AWC","From a lab pressure plate test at 1/3 bar","From the trend in that sensor's readings as the profile drains toward field capacity, such as early season after saturation with low ET","From the wilting point plus AWC"], a: 2,
    why: "FCobs comes from the sensor's own data at a known wet condition. SWD = (θFC,obs − θv) Rd then cancels much of the sensor bias and spatial error.",
    eq: null, calc: "swd-fcobs", fig: null, table: null },
  { id: "6-027", ch: 6, sec: "6.5.1", page: 123, type: "recall", level: 2,
    q: "Which instruments are used to measure leaf water potential?",
    opts: ["Pressure chambers and thermocouple psychrometers","Tensiometers and neutron probes","Infrared thermometers and pyranometers","TDR probes and gypsum blocks"], a: 0,
    why: "Leaf water potential is measured with a pressure chamber or thermocouple psychrometer. Infrared thermometers measure canopy temperature, and tensiometers measure soil tension.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-028", ch: 6, sec: "6.5.1", page: 123, type: "recall", level: 2,
    q: "Stegman (1983) found midafternoon threshold leaf water potentials for corn of about",
    opts: ["−2 to −3 bars","−12 to −12.5 bars","−30 to −35 bars","−0.1 to −0.5 bars"], a: 1,
    why: "The corn thresholds were about −12 to −12.5 bars in midafternoon. They depend on air temperature, much as fdc depends on ET.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-029", ch: 6, sec: "6.5.2", page: 124, type: "recall", level: 2,
    q: "Wanjura et al. (1995) defined the time-temperature threshold (TTT) as",
    opts: ["the temperature at which leaves wilt","the canopy minus air temperature at solar noon","the days needed for roots to reach full depth","the time accumulated above a specific temperature in one day by a crop"], a: 3,
    why: "TTT counts the daily time the canopy is above a threshold temperature. If it exceeds a time threshold, irrigation is needed. Both thresholds must be set for the crop.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-030", ch: 6, sec: "6.5.3", page: 124, type: "recall", level: 1,
    q: "What color does Kentucky bluegrass turn when under water stress?",
    opts: ["Reddish purple","Bright yellow","Blue-green","Pale white"], a: 2,
    why: "Stressed plants often turn darker, and bluegrass turns a blue-green color. Visual signs are useful but often appear too late to prevent losses.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-031", ch: 6, sec: "6.6", page: 125, type: "recall", level: 2,
    q: "Lo et al. (2016) estimated what share of Nebraska center pivot fields could cut pumping by at least 1 in using VRI to account for AWC variation?",
    opts: ["3%","13%","30%","50%"], a: 1,
    why: "The study found about 13% of pivot fields could reduce pumping by at least one inch by matching irrigation to spatial AWC variation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-032", ch: 6, sec: "6.6", page: 125, type: "recall", level: 2,
    q: "VRI prescription maps are often based on which data?",
    opts: ["Soil maps and yield maps, with soil properties often correlated to ECa or elevation","Only the field boundary","Only weather station ET","Only the pump curve"], a: 0,
    why: "Kranz et al. (2014) note maps are often built from soil and yield maps. Apparent electrical conductivity, elevation and remote sensing help describe the variability.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-033", ch: 6, sec: "6.2", page: 108, type: "concept", level: 3,
    q: "Why is the allowable depletion fraction (fdc) smaller on hot, high-ET days?",
    opts: ["Roots grow shallower on hot days","Hot weather raises the wilting point","High ET increases the soil's AWC","Plants cannot extract water fast enough to meet high demand once the soil dries, so less depletion is allowed"], a: 3,
    why: "At high atmospheric demand, stress starts at a wetter soil condition. Table 6.1 shows corn falling from 0.88 at 0.08 in/d to 0.40 at 0.39 in/d.",
    eq: null, calc: null, fig: null, table: "6.1" },
  { id: "6-034", ch: 6, sec: "6.2", page: 108, type: "concept", level: 1,
    q: "What is deficit (limited) irrigation?",
    opts: ["Irrigating only at night","Irrigating only when soil reaches wilting point","Applying less water than full crop needs, so ET and yield are below maximum","Applying more water than ET to leach salts"], a: 2,
    why: "With deficit irrigation, crop ET is less than needed for maximum yield on purpose. Most of this book targets maximum or near maximum yield.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-035", ch: 6, sec: "6.2", page: 109, type: "concept", level: 2,
    q: "How does the scheduling goal for turf and landscapes differ from field crops?",
    opts: ["Landscapes use the same fdc as corn","Turf always needs maximum ET to survive","The goal is acceptable appearance or function, not maximum biomass, so a utility turf needs less water than a golf green","Turf scheduling ignores soil water"], a: 2,
    why: "For landscapes and turf the objective is appearance or function. A high-quality golf green needs more water than low-maintenance utility turf.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-036", ch: 6, sec: "6.3", page: 110, type: "concept", level: 2,
    q: "If irrigation is applied exactly when SWD equals AD, what is the largest depth the root zone can hold without deep percolation?",
    opts: ["A depth equal to AD (the current SWD)","A depth equal to TAW","A depth equal to MB","Any depth, since excess runs off"], a: 0,
    why: "Infiltration should not exceed SWD. When SWD = AD, the root zone can store AD, such as 2.7 in in Example 6.1. Anything more percolates.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-037", ch: 6, sec: "6.3.1", page: 110, type: "concept", level: 2,
    q: "Why does an error in the assumed minimum root depth for seedlings matter little?",
    opts: ["Seedlings use very little water, so the error has very little effect on the water balance and scheduling","Seedlings do not take up water","The minimum depth is fixed by law","Roots grow too fast for it to matter"], a: 0,
    why: "The book states that an error in RdMIN has very little effect on the water balance. Early season ET is small and the root zone grows quickly toward RdMAX.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-038", ch: 6, sec: "6.3.1", page: 111, type: "concept", level: 3,
    q: "What happens to the extraction pattern if irrigations do not refill the whole root zone to field capacity?",
    opts: ["Extraction becomes uniform with depth","More water is taken from shallow depths, leaving a sandwiched dry layer between the upper and lower root zone","Roots stop using the top quarter","The 4-3-2-1 pattern still holds exactly"], a: 1,
    why: "The 4-3-2-1 rule applies only when the root zone is nearly refilled. Light irrigations wet only the top, so roots draw more there and a dry layer forms below it.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-039", ch: 6, sec: "6.4", page: 113, type: "concept", level: 1,
    q: "How do a shallow root zone or a coarse soil affect irrigation?",
    opts: ["Both allow less frequent and larger irrigations","Both require lighter and more frequent irrigations","Both require larger but more frequent irrigations","Neither affects frequency"], a: 1,
    why: "A small TAW means a small AD, so TMAX = AD / ET is short. Deep roots on medium-textured soils allow larger, less frequent applications.",
    eq: "6.8", calc: "eq-6.8", fig: null, table: null },
  { id: "6-040", ch: 6, sec: "6.4", page: 113, type: "concept", level: 2,
    q: "A pivot applies a 0.9 in effective depth even though AD is 2.7 in. Is that acceptable?",
    opts: ["No, each irrigation must equal AD","Yes, as long as the interval is set by de / ET instead of TMAX","No, it always causes deep percolation","Yes, but only if ET is above 0.5 in/d"], a: 1,
    why: "The interval does not have to equal TMAX. With de = 0.9 in and ET = 0.3 in/d the interval is 3 d, which keeps SWD well above AD.",
    eq: "6.9", calc: "eq-6.9", fig: null, table: null },
  { id: "6-041", ch: 6, sec: "6.4", page: 113, type: "concept", level: 2,
    q: "What are the two basic goals of irrigation management stated with the LD and ED concepts?",
    opts: ["Do not let the deficit exceed AD before water is applied, and do not let infiltration exceed SWD","Apply the same depth every week, and never irrigate after rain","Keep the soil at field capacity, and keep runoff at zero","Maximize ET and minimize transpiration"], a: 0,
    why: "Irrigating by the LD avoids stress, and waiting until the ED makes sure the root zone can hold the effective depth plus the rain allowance.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-042", ch: 6, sec: "6.4", page: 114, type: "concept", level: 2,
    q: "Why should a center pivot manager keep records at both a beginning and an ending position?",
    opts: ["The system reaches the ending position last, so irrigation must arrive before AD is exceeded at both points","The beginning position always has a different soil","Only the ending position gets ET","It doubles the sampling to meet regulations"], a: 0,
    why: "If LD at a location is 2 d but the pivot needs 3 d to get there, that spot will be 1 d late. Tracking both start and stop positions catches this.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-043", ch: 6, sec: "6.4", page: 115, type: "concept", level: 2,
    q: "Why do humid and semihumid regions use a rainfall allowance in the earliest date calculation?",
    opts: ["Rain often follows irrigation, and leaving room to store it avoids deep percolation and saves irrigation water","Rain always runs off, so it must be subtracted","It raises the AD","It makes the latest date later"], a: 0,
    why: "ED = (ra + dep − SWD) / ETf. Leaving room for rain means more of it becomes effective and less water percolates. In arid areas ra can be small.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-044", ch: 6, sec: "6.4.1", page: 117, type: "concept", level: 1,
    q: "In the checkbook analogy of Eq. 6.19, which are the deposits and which is the withdrawal?",
    opts: ["Deposits are irrigation, rain, and upward flow, the withdrawal is ET","Deposits are ET and rain, the withdrawal is irrigation","Deposits are runoff and drainage, the withdrawal is rain","Deposits are irrigation only, withdrawals are rain and ET"], a: 0,
    why: "AW is the balance. Effective irrigation, effective rain and upward flow add to it, ET takes from it, and going below MB costs a penalty such as lost yield.",
    eq: "6.19", calc: "eq-6.18-6.25", fig: null, table: null },
  { id: "6-045", ch: 6, sec: "6.4.1", page: 117, type: "concept", level: 2,
    q: "Why are runoff and deep percolation not written in Eq. 6.18 and 6.19?",
    opts: ["They are included in ET","They are always zero","The equations use effective precipitation and effective irrigation, which already exclude water that does not stay in the root zone","They are added once a month"], a: 2,
    why: "de and Pe are limited to SWD (Eq. 6.20 and 6.21), so any excess is assumed lost as runoff or deep percolation and never enters the balance.",
    eq: "6.20", calc: "eq-6.18-6.25", fig: null, table: null },
  { id: "6-046", ch: 6, sec: "6.4.1", page: 117, type: "concept", level: 2,
    q: "Which forecast ET values does the book suggest for LD and ED calculations?",
    opts: ["Zero, since the future is unknown","Reference ET for the coldest month","The peak design ET always","Long-term average ET for the crop stage, or the ET of the past few days if similar weather is expected"], a: 3,
    why: "Table 6.4 gives long-term water use by stage. Alternatively, if the weather is expected to stay similar, the recent few days of ET make a fair forecast.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-047", ch: 6, sec: "6.4.1", page: 117, type: "concept", level: 3,
    q: "Why is upward flow from a water table usually largest in medium-textured soils?",
    opts: ["Clay soils conduct water fastest","Sandy soils have the highest capillary rise","Medium soils combine enough capillary potential with enough unsaturated conductivity","Upward flow depends only on depth, not texture"], a: 2,
    why: "Sands lose conductivity quickly above the water table and supply little potential. Clays have strong potential but low conductivity. Medium textures balance both.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-048", ch: 6, sec: "6.4.1", page: 118, type: "concept", level: 3,
    q: "Annual crop roots grow into soil drier than field capacity. How does that affect the earliest date (ED)?",
    opts: ["ED moves later because the deficit is smaller","ED moves earlier because the new soil adds room to store water","ED does not change","ED becomes undefined"], a: 1,
    why: "Roots growing into drier soil add to SWD (ΔSWD in Eq. 6.22), so there is more room to store irrigation and ED decreases. LD may increase or decrease depending on that soil's deficit and fdc.",
    eq: "6.22", calc: "eq-6.22-6.25", fig: null, table: null },
  { id: "6-049", ch: 6, sec: "6.4.1", page: 119, type: "concept", level: 2,
    q: "What is the benefit of depleting soil water late in the season (programmed depletion)?",
    opts: ["It raises the water table","It increases yield above maximum","It leaves room to store off-season precipitation, which reduces irrigation needs","It eliminates the need for a rainfall allowance"], a: 2,
    why: "Storing off-season precipitation in an emptied profile is an effective way to reduce irrigation requirements in semiarid and subhumid regions, as Figure 6.12 illustrates.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-050", ch: 6, sec: "6.4.2", page: 120, type: "concept", level: 2,
    q: "What is the main drawback of the simplified checkbook methods (irrigating when de is used up, or weekly ΣET − ΣPe)?",
    opts: ["They ignore effective irrigation","They require hourly weather data","They overestimate rain","Applications lag behind water use, which may stress crops on low AWC soils or shallow roots"], a: 3,
    why: "Both methods react after the water is used. Where the soil reservoir is small, that lag can cause stress before water is applied.",
    eq: "6.26", calc: "eq-6.26", fig: null, table: null },
  { id: "6-051", ch: 6, sec: "6.4.3", page: 121, type: "concept", level: 2,
    q: "What is a key limitation of scheduling by threshold soil water tension?",
    opts: ["It cannot detect dry soil","It does not tell how much water the soil can hold at each irrigation, and it is hard to predict the latest date","It works only in clay soils","Sensors must be at the soil surface"], a: 1,
    why: "A threshold says when, not how much. Frequent readings or graphical extrapolation (Figure 6.13) help with timing, but depth still needs a SWD estimate.",
    eq: null, calc: null, fig: null, table: "6.6" },
  { id: "6-052", ch: 6, sec: "6.4.3", page: 122, type: "concept", level: 2,
    q: "How can the number of soil water monitoring locations be reduced?",
    opts: ["Sample only at the surface","Install one sensor at the pivot point","Use checkbook accounting together with soil water sensing","Measure only after rain"], a: 2,
    why: "The book notes that combining checkbook accounting with sensing reduces the number of locations needed, because the balance fills in between measurements.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-053", ch: 6, sec: "6.4.3", page: 122, type: "concept", level: 3,
    q: "Why track SWD with an observed field capacity, SWD = (θFC,obs − θv)Rd, instead of using absolute θv?",
    opts: ["It removes the need to know root depth","Much of the sensor and spatial uncertainty cancels when the reading is compared with the same sensor's own FC","It makes the AWC larger","It avoids needing ET data"], a: 1,
    why: "Singh et al. (2020) manage trends in SWD from each sensor's observed FC. Offsets in the sensor and local soil cancel in the difference.",
    eq: null, calc: "swd-fcobs", fig: null, table: null },
  { id: "6-054", ch: 6, sec: "6.4.3", page: 122, type: "concept", level: 3,
    q: "When should stress-prone areas (low AWC, steep slopes, ends of furrow runs) be included in sampling?",
    opts: ["Only after harvest","Always, even if tiny","Never, because they skew the average","When they represent a significant portion of the irrigated area"], a: 3,
    why: "Sampling stress-prone spots is good if they are a significant share. Managing the whole field to a tiny dry spot would over-irrigate the rest.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-055", ch: 6, sec: "6.5", page: 123, type: "concept", level: 2,
    q: "What advantage do plant status indicators have over soil water measurements?",
    opts: ["They are cheaper and faster than any soil method","They integrate soil water, atmospheric demand, and plant characteristics, because plants respond to their own tissue water status","They predict the latest date easily","They do not need thresholds"], a: 1,
    why: "Plants respond to water status in their tissues. Indicators capture soil, weather and plant factors together, though they still need thresholds and lack predictability.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-056", ch: 6, sec: "6.5.1", page: 123, type: "concept", level: 2,
    q: "Which is a limitation of leaf water potential for scheduling?",
    opts: ["It works only at night","It is not a direct measure of plant water","It is time consuming, must be done in a narrow midday window, and needs many samples","It requires a weather station"], a: 2,
    why: "It is a direct measure of plant water status, but thresholds are crop specific, it lacks predictability, it is labor intensive, and the mean needs many samples.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-057", ch: 6, sec: "6.5.2", page: 123, type: "concept", level: 1,
    q: "Why are stressed plant canopies warmer than well-watered canopies?",
    opts: ["Dry soil heats the air above the canopy only","Stressed leaves absorb less sunlight","Less transpiration means less evaporative cooling of the leaves","Stressed plants grow taller"], a: 2,
    why: "Evaporation of water cools leaves. When stomata close under stress, transpiration drops and leaf temperature rises, which infrared thermometers detect.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-058", ch: 6, sec: "6.5.2", page: 124, type: "concept", level: 3,
    q: "The crop water stress index (CWSI) depends on the canopy minus air temperature difference and what else?",
    opts: ["The wind direction only","Soil water tension at 30 in","The vapor pressure deficit, with baselines for a non-transpiring and a non-stressed canopy","The leaf area index only"], a: 2,
    why: "Jackson et al. (1981) related DT to VPD between a non-stressed baseline and a non-transpiring upper limit. Bare soil in view, wind and clouds complicate readings.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-059", ch: 6, sec: "6.5.2", page: 124, type: "concept", level: 3,
    q: "Peters and Evett automated a pivot using canopy temperature and the TTT method. Why did it matter that the pivot had LEPA drops?",
    opts: ["LEPA allowed higher pressure","LEPA drops measured the temperature","The canopy was not wetted, so irrigation did not cool leaves and distort the temperature readings","LEPA removed the need for a threshold"], a: 2,
    why: "Wet leaves cool by evaporation regardless of plant water status. Applying water below the canopy kept the infrared readings meaningful.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-060", ch: 6, sec: "6.5.3", page: 124, type: "concept", level: 1,
    q: "What is the main problem with using visual symptoms such as leaf rolling or wilting to schedule irrigation?",
    opts: ["They only appear at night","They never appear in corn","They require expensive sensors","They often appear too late, after yield and economic losses have occurred"], a: 3,
    why: "Visual signs are useful but often come too late, and like other plant indicators they do not predict ahead.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-061", ch: 6, sec: "6.5.4", page: 124, type: "concept", level: 2,
    q: "Scheduling by critical growth stages is common in Extension publications. What does the book say it needs?",
    opts: ["No calibration at all","Local calibration for soil, crop and climate conditions","A pressure chamber","A neutron probe"], a: 1,
    why: "The method has merit, but the right stages and amounts vary by soil, crop and climate, so local calibration is needed.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-062", ch: 6, sec: "6.6", page: 125, type: "concept", level: 2,
    q: "A pivot field starts the season at field capacity. With VRI, which soils need irrigation first?",
    opts: ["Soils with lower AWC, while heavier soils can be left to use stored water","Soils with higher AWC","All soils at the same time","Low spots first"], a: 0,
    why: "With the same starting depletion, low AWC soils reach AD first. Leaving heavier soils unirrigated mines their stored water (Miller et al., 2018).",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-063", ch: 6, sec: "6.6", page: 125, type: "concept", level: 2,
    q: "How do VRI avoidance zones help with chemigation on a field crossed by a waterway?",
    opts: ["They speed the pivot over the waterway","Water and chemical are shut off over the waterway, so chemigation can continue on the rest of the field","They apply extra chemical near the waterway","They let the pivot skip the field corners"], a: 1,
    why: "Regulations prevent chemical application on surface water bodies. An avoidance zone turns off application over the waterway, low spots, or other noncropped areas.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-064", ch: 6, sec: "6.6", page: 125, type: "concept", level: 3,
    q: "After the stored-water mining prescription of Figure 6.16 is used twice, what does the book say comes next?",
    opts: ["The field must be refilled to field capacity","SWD equals AD in each zone, so uniform irrigation can replace ET","VRI must continue all season with the same map","Irrigation stops for the season"], a: 1,
    why: "The map is used twice to draw down heavier soils. Then every zone sits at AD and a uniform application replaces ET. Sensors in each zone are recommended.",
    eq: null, calc: null, fig: "6.16", table: null },
  { id: "6-065", ch: 6, sec: "6.2", page: 108, type: "calc", level: 1,
    q: "A crop's critical fraction remaining is frc = 0.65. What is the maximum allowable fraction depleted?",
    opts: ["0.35","0.65","1.65","0.54"], a: 0,
    why: "fdc = 1 − frc = 1 − 0.65 = 0.35. 0.65 confuses the two fractions.",
    eq: "6.1", calc: "eq-6.1", fig: null, table: null },
  { id: "6-066", ch: 6, sec: "6.3", page: 109, type: "calc", level: 1,
    q: "A root zone is 30 in deep in a soil with AWC = 0.15 in/in. What is TAW?",
    opts: ["2.0 in","0.45 in","4.5 in","5.4 in"], a: 2,
    why: "TAW = Rd × AWC = 30 × 0.15 = 4.5 in. 5.4 in would be a 36-in root zone.",
    eq: "6.2", calc: "eq-6.2-6.5", fig: null, table: null },
  { id: "6-067", ch: 6, sec: "6.3", page: 109, type: "calc", level: 2,
    q: "Corn roots extend 4 ft in a soil with AWC = 0.12 in/in. What is TAW?",
    opts: ["1.4 in","0.48 in","4.0 in","5.8 in"], a: 3,
    why: "Convert depth to inches: 48 in × 0.12 in/in = 5.76, about 5.8 in. 0.48 in forgets the conversion from feet.",
    eq: "6.2", calc: "eq-6.2-6.5", fig: null, table: null },
  { id: "6-068", ch: 6, sec: "6.3", page: 109, type: "calc", level: 3,
    q: "Tomato roots reach 48 in in a soil with layers 0 to 10 in (AWC 0.23 in/in), 10 to 38 in (0.15 in/in), and 38 to 60 in (0.20 in/in). What is TAW?",
    opts: ["9.3 in","10.9 in","8.5 in","11.0 in"], a: 2,
    why: "TAW = 0.23×10 + 0.15×28 + 0.20×(48 − 38) = 2.3 + 4.2 + 2.0 = 8.5 in. 10.9 in counts the whole 22-in bottom layer below the roots, and 11.0 in applies the top layer AWC to all 48 in.",
    eq: "6.3", calc: "eq-6.3", fig: null, table: null },
  { id: "6-069", ch: 6, sec: "6.3", page: 109, type: "calc", level: 2,
    q: "A soil has 18 in with AWC = 0.18 in/in over sand with AWC = 0.10 in/in. Roots are 36 in deep. What is TAW?",
    opts: ["6.5 in","5.0 in","3.6 in","5.8 in"], a: 1,
    why: "TAW = 0.18×18 + 0.10×(36 − 18) = 3.24 + 1.80 = 5.04, about 5.0 in. 6.5 in uses 0.18 for the whole root zone, and 3.6 in uses 0.10.",
    eq: "6.3", calc: "eq-6.3", fig: null, table: null },
  { id: "6-070", ch: 6, sec: "6.3", page: 109, type: "calc", level: 2,
    q: "TAW is 5.4 in and fdc = 0.55. What is the allowable depletion?",
    opts: ["9.8 in","2.4 in","5.4 in","3.0 in"], a: 3,
    why: "AD = fdc × TAW = 0.55 × 5.4 = 2.97, about 3.0 in. 2.4 in is the minimum balance (0.45 × 5.4).",
    eq: "6.4", calc: "eq-6.2-6.5", fig: null, table: null },
  { id: "6-071", ch: 6, sec: "6.3", page: 109, type: "calc", level: 2,
    q: "TAW is 5.4 in and fdc = 0.55. What is the minimum balance (MB)?",
    opts: ["3.0 in","2.4 in","0.45 in","5.4 in"], a: 1,
    why: "frc = 1 − 0.55 = 0.45 and MB = 0.45 × 5.4 = 2.43, about 2.4 in. 3.0 in is AD.",
    eq: "6.5", calc: "eq-6.2-6.5", fig: null, table: null },
  { id: "6-072", ch: 6, sec: "6.3", page: 110, type: "calc", level: 2,
    q: "Root zone depth is 4 ft, AWC = 0.14 in/in, and fdc = 0.50. What are TAW, AD, and MB?",
    opts: ["TAW 6.7 in, AD 3.4 in, MB 6.7 in","TAW 0.56 in, AD 0.28 in, MB 0.28 in","TAW 6.7 in, AD 3.4 in, MB 3.4 in","TAW 5.0 in, AD 2.5 in, MB 2.5 in"], a: 2,
    why: "TAW = 48 × 0.14 = 6.72 in. AD = 0.50 × 6.72 = 3.36 in and MB = 0.50 × 6.72 = 3.36 in. With fdc = 0.5, AD and MB are equal.",
    eq: "6.4", calc: "eq-6.2-6.5", fig: null, table: null },
  { id: "6-073", ch: 6, sec: "6.3.1", page: 111, type: "calc", level: 2,
    q: "A crop has RdMIN = 0.5 ft, RdMAX = 4.5 ft, and reaches full depth 80 d after germination. What is the root depth 40 d after germination?",
    opts: ["2.5 ft","2.25 ft","2.0 ft","4.5 ft"], a: 0,
    why: "Rf = 40 / 80 = 0.5 and Rd = 0.5 + (4.5 − 0.5)(0.5) = 2.5 ft. 2.0 ft forgets to add RdMIN, and 2.25 ft multiplies RdMAX by Rf.",
    eq: "6.6", calc: "eq-6.6-6.7", fig: null, table: null },
  { id: "6-074", ch: 6, sec: "6.3.1", page: 111, type: "calc", level: 3,
    q: "Corn starts with a 6-in root zone and reaches 48 in at 75 d after germination. What is the root depth 30 d after germination?",
    opts: ["About 23 in","About 19 in","About 29 in","About 6 in"], a: 0,
    why: "Rf = 30 / 75 = 0.4. Rd = 6 + (48 − 6)(0.4) = 22.8 in, about 23 in. 19 in is 48 × 0.4 without the minimum depth.",
    eq: "6.7", calc: "eq-6.6-6.7", fig: null, table: null },
  { id: "6-075", ch: 6, sec: "6.3.1", page: 111, type: "calc", level: 3,
    q: "RdMIN = 0.5 ft, RdMAX = 4 ft, and Dtm = 90 d. What root depth should be used 100 d after germination?",
    opts: ["4.4 ft","4.0 ft, because the root growth factor cannot exceed 1","3.9 ft","0.5 ft"], a: 1,
    why: "Eq. 6.6 describes root depth before the date of maximum rooting. After Dtm the root zone stays at RdMAX = 4.0 ft. 4.4 ft extrapolates past full depth with Rf = 1.11.",
    eq: "6.6", calc: "eq-6.6-6.7", fig: null, table: null },
  { id: "6-076", ch: 6, sec: "6.3.1", page: 111, type: "calc", level: 1,
    q: "Using the 4-3-2-1 rule, a crop with a 4-ft root zone uses 2.5 in between irrigations. How much comes from the top foot?",
    opts: ["0.63 in","1.0 in","0.75 in","0.25 in"], a: 1,
    why: "The top quarter supplies 40%: 0.40 × 2.5 = 1.0 in. 0.63 in assumes equal extraction from each foot, and 0.25 in is the bottom foot.",
    eq: null, calc: "extraction-4321", fig: null, table: null },
  { id: "6-077", ch: 6, sec: "6.3.1", page: 111, type: "calc", level: 2,
    q: "With a 3-ft root zone, plants extract 1.8 in between irrigations. Using the 4-3-2-1 rule, how much comes from the bottom 9 in?",
    opts: ["0.60 in","0.45 in","0.72 in","0.18 in"], a: 3,
    why: "The bottom quarter (27 to 36 in) supplies 10%: 0.10 × 1.8 = 0.18 in. 0.72 in is the top quarter's 40%.",
    eq: null, calc: "extraction-4321", fig: null, table: null },
  { id: "6-078", ch: 6, sec: "6.4", page: 112, type: "calc", level: 1,
    q: "AD is 2.4 in and average ET is 0.30 in/d. What is the maximum interval between irrigations?",
    opts: ["7 d","0.72 d","12.5 d","8 d"], a: 3,
    why: "TMAX = AD / ET = 2.4 / 0.30 = 8 d. 0.72 multiplies instead of dividing.",
    eq: "6.8", calc: "eq-6.8", fig: null, table: null },
  { id: "6-079", ch: 6, sec: "6.4", page: 112, type: "calc", level: 3,
    q: "A 36-in root zone has AWC = 0.16 in/in and fdc = 0.50. ET averages 0.32 in/d. What is TMAX?",
    opts: ["2.9 d","18 d","5 d","9 d"], a: 3,
    why: "TAW = 36 × 0.16 = 5.76 in, AD = 0.5 × 5.76 = 2.88 in, and TMAX = 2.88 / 0.32 = 9 d. 18 d uses TAW instead of AD.",
    eq: "6.8", calc: "eq-6.8", fig: null, table: null },
  { id: "6-080", ch: 6, sec: "6.4", page: 113, type: "calc", level: 1,
    q: "Each irrigation puts 0.8 in of effective water in the root zone and ET is 0.25 in/d. What is the irrigation interval?",
    opts: ["2.4 d","0.2 d","4.0 d","3.2 d"], a: 3,
    why: "T = de / ET = 0.8 / 0.25 = 3.2 d. 0.2 multiplies the two.",
    eq: "6.9", calc: "eq-6.9", fig: null, table: null },
  { id: "6-081", ch: 6, sec: "6.4", page: 113, type: "calc", level: 3,
    q: "A pivot applies 1.0 in gross with ELQ = 85%. ET is 0.28 in/d. About how often should it irrigate?",
    opts: ["Every 3 d","Every 3.6 d","Every 4.2 d","Every 2.4 d"], a: 0,
    why: "de = 1.0 × 0.85 = 0.85 in and T = 0.85 / 0.28 = 3.0 d. 3.6 d uses the gross depth as if it were all effective.",
    eq: "6.9", calc: "eq-6.9", fig: null, table: null },
  { id: "6-082", ch: 6, sec: "6.4.2", page: 120, type: "calc", level: 1,
    q: "A grower irrigates whenever the effective depth is used up. A 0.6 in effective rain falls and ET is 0.20 in/d. How long should the next irrigation be delayed?",
    opts: ["6 d","0.12 d","3 d","2 d"], a: 2,
    why: "Delay = Pe / ET = 0.6 / 0.20 = 3 d, assuming the grower was not behind before the rain.",
    eq: "6.9", calc: "eq-6.9", fig: null, table: null },
  { id: "6-083", ch: 6, sec: "6.4", page: 113, type: "calc", level: 1,
    q: "AD = 2.0 in, current SWD = 1.1 in, and forecast ET = 0.30 in/d. What is the latest date to irrigate?",
    opts: ["3 d from now","6.7 d from now","3.7 d from now","10 d from now"], a: 0,
    why: "LD = (AD − SWD) / ETf = (2.0 − 1.1) / 0.30 = 3 d. 6.7 d uses AD alone and 3.7 d uses SWD alone.",
    eq: "6.10", calc: "eq-6.10-6.11", fig: null, table: null },
  { id: "6-084", ch: 6, sec: "6.4", page: 113, type: "calc", level: 2,
    q: "Using the balance form, available water AW = 3.2 in, MB = 2.5 in, and forecast ET = 0.35 in/d. What is LD?",
    opts: ["16 d","9 d","2 d","7 d"], a: 2,
    why: "LD = (AW − MB) / ETf = (3.2 − 2.5) / 0.35 = 2 d. 9 d divides AW by ET and ignores the minimum balance.",
    eq: "6.11", calc: "eq-6.10-6.11", fig: null, table: null },
  { id: "6-085", ch: 6, sec: "6.4", page: 114, type: "calc", level: 3,
    q: "A 30-in root zone has AWC = 0.15 in/in and fdc = 0.50. A soil check shows fr = 0.70, and forecast ET is 0.30 in/d. What is LD?",
    opts: ["7.5 d","4.5 d","3 d","1.5 d"], a: 2,
    why: "TAW = 4.5 in and AD = 2.25 in. fd = 1 − 0.70 = 0.30, so SWD = 0.30 × 4.5 = 1.35 in. LD = (2.25 − 1.35) / 0.30 = 3 d. 7.5 d is AD / ET, ignoring the current deficit, and 4.5 d is SWD / ET.",
    eq: "6.10", calc: "ld-ed-window", fig: null, table: null },
  { id: "6-086", ch: 6, sec: "6.4", page: 115, type: "calc", level: 2,
    q: "Rainfall allowance ra = 0.5 in, planned effective depth dep = 1.0 in, SWD = 1.2 in, and ETf = 0.30 in/d. What is the earliest date to irrigate?",
    opts: ["5 d from now","1 d from now","2.3 d from now","0 d (now)"], a: 1,
    why: "ED = (ra + dep − SWD) / ETf = (0.5 + 1.0 − 1.2) / 0.30 = 1 d. 5 d adds SWD instead of subtracting it.",
    eq: "6.16", calc: "eq-6.16-6.17", fig: null, table: null },
  { id: "6-087", ch: 6, sec: "6.4", page: 115, type: "calc", level: 3,
    q: "ra = 0.3 in, dep = 0.6 in, SWD = 1.1 in, and ETf = 0.30 in/d. What is the earliest date?",
    opts: ["Now, because the ED calculation is negative (about −0.7 d)","0.7 d from now","3.0 d from now","6.7 d from now"], a: 0,
    why: "ED = (0.3 + 0.6 − 1.1) / 0.30 = −0.67 d. A negative ED means there is already room for the irrigation and the rain allowance, so irrigation can start now.",
    eq: "6.16", calc: "eq-6.16-6.17", fig: null, table: null },
  { id: "6-088", ch: 6, sec: "6.4", page: 115, type: "calc", level: 3,
    q: "Using the balance form, TAW = 5.0 in, AW = 4.2 in, ra = 0.5 in, dep = 0.9 in, and ETf = 0.25 in/d. What is ED?",
    opts: ["8.8 d","5.6 d","2.4 d","1.6 d"], a: 2,
    why: "SWD = TAW − AW = 0.8 in. ED = (0.5 + 0.9 − 0.8) / 0.25 = 2.4 d. 8.8 d adds the deficit instead of subtracting it, and 5.6 d ignores the deficit.",
    eq: "6.17", calc: "eq-6.16-6.17", fig: null, table: null },
  { id: "6-089", ch: 6, sec: "6.4", page: 113, type: "calc", level: 1,
    q: "A non-layered soil has θv = 0.28 and θwp = 0.12 in a 24-in root zone. What is the available water?",
    opts: ["0.16 in","6.7 in","2.9 in","3.8 in"], a: 3,
    why: "AW = (θv − θwp) Rd = 0.16 × 24 = 3.84, about 3.8 in. 6.7 in uses θv alone and 0.16 forgets the root depth.",
    eq: "6.12", calc: "eq-6.12", fig: null, table: null },
  { id: "6-090", ch: 6, sec: "6.4", page: 113, type: "calc", level: 1,
    q: "A soil check gives fr = 0.60 in a 36-in root zone with AWC = 0.18 in/in. What is AW?",
    opts: ["0.11 in","2.6 in","6.5 in","3.9 in"], a: 3,
    why: "AW = fr × AWC × Rd = 0.60 × 0.18 × 36 = 3.89, about 3.9 in. 2.6 in uses fd = 0.40 instead of fr.",
    eq: "6.12", calc: "eq-6.12", fig: null, table: null },
  { id: "6-091", ch: 6, sec: "6.4", page: 113, type: "calc", level: 1,
    q: "TAW is 4.4 in and the fraction of available water remaining is 0.55. What is AW?",
    opts: ["2.4 in","2.0 in","8.0 in","0.55 in"], a: 0,
    why: "AW = fr × TAW = 0.55 × 4.4 = 2.42, about 2.4 in (Eq. 6.12c). 2.0 in is the SWD.",
    eq: "6.12", calc: "eq-6.12", fig: null, table: null },
  { id: "6-092", ch: 6, sec: "6.4", page: 114, type: "calc", level: 2,
    q: "TAW = 4.8 in and the fraction depleted is 0.35. What is the SWD?",
    opts: ["13.7 in","3.1 in","0.35 in","1.7 in"], a: 3,
    why: "SWD = fd × TAW = 0.35 × 4.8 = 1.68, about 1.7 in. 3.1 in is the AW remaining.",
    eq: "6.14", calc: "eq-6.14-6.15", fig: null, table: null },
  { id: "6-093", ch: 6, sec: "6.4", page: 114, type: "calc", level: 3,
    q: "Three 12-in layers have θv of 0.30, 0.26, and 0.22 and wilting points of 0.14, 0.12, and 0.10. Roots go 36 in. What is AW?",
    opts: ["9.4 in","5.0 in","4.3 in","1.7 in"], a: 1,
    why: "AW = 12(0.16) + 12(0.14) + 12(0.12) = 1.92 + 1.68 + 1.44 = 5.04 in. 9.4 in uses θv without subtracting θwp.",
    eq: "6.13", calc: "eq-6.13", fig: null, table: null },
  { id: "6-094", ch: 6, sec: "6.4", page: 114, type: "calc", level: 1,
    q: "TAW is 5.0 in and AW is 3.1 in. What is SWD?",
    opts: ["1.9 in","8.1 in","3.1 in","1.6 in"], a: 0,
    why: "TAW = AW + SWD, so SWD = 5.0 − 3.1 = 1.9 in.",
    eq: "6.15", calc: "eq-6.14-6.15", fig: null, table: null },
  { id: "6-095", ch: 6, sec: "6.4.3", page: 122, type: "calc", level: 2,
    q: "A sensor's observed field capacity reading is 0.32 and today it reads 0.26. It represents a 24-in root zone. What is SWD?",
    opts: ["1.4 in","6.2 in","7.7 in","0.06 in"], a: 0,
    why: "SWD = (θFC,obs − θv) Rd = 0.06 × 24 = 1.44, about 1.4 in. 6.2 in uses θv × Rd.",
    eq: null, calc: "swd-fcobs", fig: null, table: null },
  { id: "6-096", ch: 6, sec: "6.4.1", page: 116, type: "calc", level: 1,
    q: "Yesterday's SWD was 1.5 in. ET was 0.30 in, effective rain was 0.40 in, and there was no irrigation or upward flow. What is today's SWD?",
    opts: ["1.6 in","2.2 in","1.4 in","1.8 in"], a: 2,
    why: "SWDi = 1.5 + 0.30 − 0 − 0.40 − 0 = 1.4 in. 2.2 in adds the rain instead of subtracting it.",
    eq: "6.18", calc: "eq-6.18-6.25", fig: null, table: null },
  { id: "6-097", ch: 6, sec: "6.4.1", page: 117, type: "calc", level: 3,
    q: "Yesterday SWD was 0.9 in, ET was 0.25 in, and an irrigation infiltrated 1.1 in in the low quarter. What is today's SWD?",
    opts: ["0.25 in","0.05 in","0 in","0.45 in"], a: 0,
    why: "dLQ (1.1) exceeds SWD (0.9), so de = 0.9 in (Eq. 6.20). SWDi = 0.9 + 0.25 − 0.9 = 0.25 in. Using the full 1.1 in gives 0.05 in and counts water that percolated.",
    eq: "6.20", calc: "eq-6.18-6.25", fig: null, table: null },
  { id: "6-098", ch: 6, sec: "6.4.1", page: 117, type: "calc", level: 2,
    q: "In the AW form of the checkbook, yesterday AW = 3.0 in, ET = 0.28 in, effective irrigation = 0.85 in, and upward flow = 0.05 in. What is today's AW?",
    opts: ["4.18 in","2.52 in","3.52 in","3.62 in"], a: 3,
    why: "AWi = 3.0 − 0.28 + 0.85 + 0.05 = 3.62 in. 3.52 in forgets the upward flow.",
    eq: "6.19", calc: "eq-6.18-6.25", fig: null, table: null },
  { id: "6-099", ch: 6, sec: "6.4.1", page: 118, type: "calc", level: 3,
    q: "Roots grow 3 in deeper into soil with AWC = 0.17 in/in that is 20% depleted. How much does the SWD increase?",
    opts: ["0.41 in","0.10 in","0.51 in","0.60 in"], a: 1,
    why: "ΔSWD = (fdo / 100%) × AWC × ΔRd = 0.20 × 0.17 × 3 = 0.10 in. 0.41 in is the added AW and 0.51 in is the added TAW.",
    eq: "6.23", calc: "eq-6.22-6.25", fig: null, table: null },
  { id: "6-100", ch: 6, sec: "6.4.1", page: 119, type: "calc", level: 3,
    q: "Roots grow 4 in deeper into soil with AWC = 0.15 in/in that still holds 90% of its available water. How much AW is added?",
    opts: ["0.06 in","0.54 in","0.60 in","3.6 in"], a: 1,
    why: "ΔAW = (fro / 100%) × AWC × ΔRd = 0.90 × 0.15 × 4 = 0.54 in. 0.06 in is the deficit added, and 0.60 in is the added TAW.",
    eq: "6.25", calc: "eq-6.22-6.25", fig: null, table: null },
  { id: "6-101", ch: 6, sec: "6.4.2", page: 120, type: "calc", level: 1,
    q: "Over a week, daily ET was 0.30, 0.28, 0.32, 0.25, 0.22, 0.30, and 0.33 in. Effective rain was 0.40 in on Monday and 0.25 in on Thursday. How much effective irrigation is needed?",
    opts: ["2.00 in","1.35 in","2.65 in","0.65 in"], a: 1,
    why: "ΣET = 2.00 in and ΣPe = 0.65 in. de = 2.00 − 0.65 = 1.35 in (Eq. 6.26). 2.65 in adds rain to ET.",
    eq: "6.26", calc: "eq-6.26", fig: null, table: null },
  { id: "6-102", ch: 6, sec: "6.4.2", page: 120, type: "calc", level: 3,
    q: "ET for the past 4 days was 0.30, 0.26, 0.34, and 0.30 in/d. Each irrigation puts on 1.2 in effective. How often should you irrigate, and how long should a 0.6 in rain delay it?",
    opts: ["Every 5 d, delay 1 d","Every 4 d, delay 3 d","Every 3 d, delay 2 d","Every 4 d, delay 2 d"], a: 3,
    why: "Average ET = 1.20 / 4 = 0.30 in/d. Interval = 1.2 / 0.30 = 4 d and delay = 0.6 / 0.30 = 2 d, assuming the rain is all effective.",
    eq: "6.9", calc: "eq-6.9", fig: null, table: null },
  { id: "6-103", ch: 6, sec: "6.4.1", page: 119, type: "calc", level: 3,
    q: "Corn on silt loam has Rd = 30 in, AWC = 0.20 in/in, and fdc = 0.45. SWD is 1.5 in at the start of the day, ET that day is 0.25 in with no rain or irrigation, and the forecast ET is 0.19 in/d. What is LD the next morning?",
    opts: ["3.8 d","6.3 d","5 d","2.7 d"], a: 2,
    why: "TAW = 6 in and AD = 2.7 in. Next day SWD = 1.5 + 0.25 = 1.75 in. LD = (2.7 − 1.75) / 0.19 = 5 d. 6.3 d forgets to update SWD for the day's ET, and 3.8 d divides by actual instead of forecast ET.",
    eq: "6.10", calc: "checkbook", fig: null, table: null },
  { id: "6-104", ch: 6, sec: "6.4.3", page: 122, type: "calc", level: 3,
    q: "Lettuce has a 12-in root zone in soil with AWC = 0.15 in/in and fdc = 0.50. A soil check shows fr = 0.75. ETf = 0.15 in/d, the planned effective depth is 0.45 in, and ra = 0.3 in. When should you irrigate?",
    opts: ["Between 2 d (ED) and 3 d (LD) from now","Between 0 d and 3 d from now","Between 3 d and 6 d from now","Between 2 d and 9 d from now"], a: 0,
    why: "TAW = 1.8 in, AD = 0.9 in, SWD = 0.25 × 1.8 = 0.45 in. LD = (0.9 − 0.45) / 0.15 = 3 d, and ED = (0.3 + 0.45 − 0.45) / 0.15 = 2 d.",
    eq: "6.16", calc: "ld-ed-window", fig: null, table: null },
  { id: "6-105", ch: 6, sec: "6.2", page: 108, type: "figure", level: 2,
    q: "In Figure 6.1b, why does the yield line start to the right of zero on the seasonal ET axis?",
    opts: ["Rain is subtracted from ET","Transpiration is negative early in the season","Yield is measured only after harvest","Some ET goes to soil water evaporation before any yield is produced"], a: 3,
    why: "Yield is linear with transpiration from the origin (6.1a). Seasonal ET includes soil evaporation, so the ET line starts after that amount is satisfied, then rises to maximum yield, the full irrigation goal.",
    eq: null, calc: null, fig: "6.1", table: null },
  { id: "6-106", ch: 6, sec: "6.2", page: 108, type: "figure", level: 2,
    q: "In Figure 6.2, relative yield stays near 100% until the fraction of available water remaining drops to about what value?",
    opts: ["About 0.25","About 0.9","About 0.5 (frc)","About 0.1"], a: 2,
    why: "The curve is flat near 100% down to frc at about 0.5, then yield falls toward zero as fr drops further.",
    eq: null, calc: null, fig: "6.2", table: null },
  { id: "6-107", ch: 6, sec: "6.3.1", page: 111, type: "figure", level: 2,
    q: "In Figure 6.3, about when does the corn root zone reach its maximum depth?",
    opts: ["About 120 d after planting","About 5 d after planting, at 1 ft","About 25 d after planting, at 2 ft","About 50 d after planting, at nearly 4 ft"], a: 3,
    why: "The dashed line runs from Rd Min near 1 ft at about 5 d to Rd Max near 3.8 ft at about 50 d, then stays flat.",
    eq: null, calc: null, fig: "6.3", table: null },
  { id: "6-108", ch: 6, sec: "6.3.1", page: 112, type: "figure", level: 1,
    q: "Figure 6.4 shows average extraction from the root zone. What share comes from the top quarter?",
    opts: ["30%","25%","40%","10%"], a: 2,
    why: "The 4-3-2-1 pattern gives 40% from the top quarter, then 30%, 20% and 10%.",
    eq: null, calc: "extraction-4321", fig: "6.4", table: null },
  { id: "6-109", ch: 6, sec: "6.4", page: 113, type: "figure", level: 2,
    q: "In the LD diagram of Figure 6.5, what does the hatched band of water represent?",
    opts: ["The soil water deficit SWD","The available water AW","Water that can be used before stress occurs, AD − SWD","Water below the wilting point"], a: 2,
    why: "The band runs from the current level down to the AD line. Dividing it by forecast ET gives LD = (AD − SWD) / ET.",
    eq: "6.10", calc: "eq-6.10-6.11", fig: "6.5", table: null },
  { id: "6-110", ch: 6, sec: "6.4", page: 115, type: "figure", level: 2,
    q: "In the ED diagram of Figure 6.7, what must happen before the irrigation is applied?",
    opts: ["Runoff must stop","The soil must reach wilting point","The deficit must equal AD","Enough water must be used so the root zone can store the effective irrigation and still have room for the rain allowance"], a: 3,
    why: "The hatched band is ra + de − SWD, the water that must be used first. Dividing by ET gives the earliest date.",
    eq: "6.16", calc: "eq-6.16-6.17", fig: "6.7", table: null },
  { id: "6-111", ch: 6, sec: "6.4", page: 116, type: "figure", level: 2,
    q: "In Figure 6.8, why do the TAW and MB lines rise from emergence and then level off?",
    opts: ["AWC increases during the season","The root zone deepens until it reaches maximum depth","ET increases until midseason","Rainfall increases the soil's capacity"], a: 1,
    why: "TAW and MB are proportional to root depth. As roots grow both rise, and once roots reach full depth they stay constant. AW should stay between them.",
    eq: null, calc: null, fig: "6.8", table: null },
  { id: "6-112", ch: 6, sec: "6.4.1", page: 116, type: "figure", level: 1,
    q: "In Figure 6.9, which flow adds water to the root zone from below?",
    opts: ["Evapotranspiration","Deep percolation","Runoff","Upward flow"], a: 3,
    why: "Upward flow from a shallow water table enters the bottom of the root zone. Deep percolation leaves through the bottom, runoff leaves at the surface, and ET leaves to the air.",
    eq: null, calc: null, fig: "6.9", table: null },
  { id: "6-113", ch: 6, sec: "6.4.1", page: 118, type: "figure", level: 3,
    q: "In Figure 6.10, with the water table 4 ft below the root zone, which soil still supplies about 0.08 in/d of upward flow?",
    opts: ["Loamy sand","Sandy loam","Clay loam","Fine sandy loam"], a: 3,
    why: "At 4 ft the fine sandy loam curve (7) is near 0.08 in/d. Sandy loam (6) is near 0.03 in/d, clay loam (5) is near zero, and the loamy sand curve ends before 3 ft.",
    eq: null, calc: null, fig: "6.10", table: null },
  { id: "6-114", ch: 6, sec: "6.4.1", page: 118, type: "figure", level: 2,
    q: "In Figure 6.10, which two soils supply almost no upward flow once the water table is about 2 ft below the root zone?",
    opts: ["Fine sandy loam and sandy loam","Sticky clay and loamy sand","Clay loam and fine sandy loam","Peat and fine sandy loam"], a: 1,
    why: "Curves 1 (sticky clay) and 2 (loamy sand) drop to near zero by about 1.7 to 2.3 ft. Fine sandy loam and sandy loam still supply flow beyond 3 ft.",
    eq: null, calc: null, fig: "6.10", table: null },
  { id: "6-115", ch: 6, sec: "6.4.1", page: 120, type: "figure", level: 1,
    q: "In Figure 6.11, between what levels was available soil water kept by checkbook scheduling?",
    opts: ["About 0 to 40%","About 10 to 30%","About 80 to 100%","About 40 to 70%"], a: 3,
    why: "Figure 6.11 shows AW kept between about 40 and 70% through the season, with frequent irrigations or rain.",
    eq: null, calc: null, fig: "6.11", table: null },
  { id: "6-116", ch: 6, sec: "6.4.1", page: 120, type: "figure", level: 2,
    q: "Figure 6.12 shows soil water falling from about 90% early in the season to about 20% at plant maturity. What practice does it illustrate?",
    opts: ["Programmed soil moisture depletion to leave room for off-season precipitation","Over irrigation late in the season","Failure of the irrigation system","Keeping the soil near field capacity"], a: 0,
    why: "Applications replace only part of ET so the profile drains to low but safe levels by maturity, leaving storage for off-season rain and snow.",
    eq: null, calc: null, fig: "6.12", table: null },
  { id: "6-117", ch: 6, sec: "6.4.3", page: 122, type: "figure", level: 2,
    q: "Figure 6.13 extrapolates tensiometer readings in a fine sandy loam. What threshold is used and when is irrigation predicted?",
    opts: ["45 cb, with irrigation needed on about day 9","10 cb, on day 2","30 cb, on day 6","80 cb, on day 12"], a: 0,
    why: "The threshold line is at 45 cb, which matches fine sandy loam in Table 6.6. The dashed projection reaches it around day 8 to 9, labeled as day 9.",
    eq: null, calc: null, fig: "6.13", table: null },
  { id: "6-118", ch: 6, sec: "6.5.1", page: 123, type: "figure", level: 2,
    q: "In Figure 6.14 for a wheat plant, where is the largest drop in water potential?",
    opts: ["Between the soil (−0.1 bar) and the seminal roots (−2.3 bars)","Between the leaf (−16.5 bars) and the atmosphere (−900 bars)","Between the nodal roots and the stem base","Within the soil"], a: 1,
    why: "Potential falls from −0.1 bar in the soil to −16.5 bars in the leaf, but the air is at −900 bars, so by far the largest drop is from leaf to atmosphere.",
    eq: null, calc: null, fig: "6.14", table: null },
  { id: "6-119", ch: 6, sec: "6.6", page: 125, type: "figure", level: 2,
    q: "In the VRI example of Figure 6.16, which zone gets the largest prescribed application?",
    opts: ["The 11 in TAW zone, with 1.5 in","The 8 in TAW zone, with 1.5 in","The 10 in TAW zone, with 1 in","The creek avoidance zone"], a: 1,
    why: "The lowest TAW soil (8 in) runs short first and gets 1.5 in. The 11 in TAW areas get 0 in so their stored water is used, and the creek is an avoidance zone.",
    eq: null, calc: null, fig: "6.16", table: null },
  { id: "6-120", ch: 6, sec: "6.4", page: 115, type: "figure", level: 2,
    q: "Figure 6.6 shows the beginning and ending positions on either side of the pivot's starting line. Why are they placed there?",
    opts: ["They are where the end gun runs","They are the wettest spots in the field","The beginning position is irrigated first in each cycle and the ending position last, so they bracket the driest conditions","They are where runoff collects"], a: 2,
    why: "Right after the start line the soil was just irrigated, while just before it the soil has waited a full cycle. Checking both makes sure neither passes AD.",
    eq: null, calc: null, fig: "6.6", table: null },
  { id: "6-121", ch: 6, sec: "6.2", page: 109, type: "table", level: 1,
    q: "From Table 6.1, what is fdc for corn (group 4) at a maximum ET of 0.35 in/d?",
    opts: ["0.50","0.43","0.35","0.25"], a: 1,
    why: "Corn is in group 4, and the 0.35 in/d column reads 0.43. 0.50 is the 0.28 in/d value.",
    eq: null, calc: "tab-6.1", fig: null, table: "6.1" },
  { id: "6-122", ch: 6, sec: "6.2", page: 109, type: "table", level: 1,
    q: "From Table 6.1, what is fdc for potato at a maximum ET of 0.24 in/d?",
    opts: ["0.55","0.35","0.45","0.25"], a: 3,
    why: "Potato is in group 1, the most sensitive group, and reads 0.25 at 0.24 in/d. 0.55 is group 4.",
    eq: null, calc: "tab-6.1", fig: null, table: "6.1" },
  { id: "6-123", ch: 6, sec: "6.2", page: 109, type: "table", level: 2,
    q: "Using Table 6.1, what is the critical fraction remaining (frc) for tomato at a maximum ET of 0.20 in/d?",
    opts: ["0.60","0.40","0.50","0.70"], a: 0,
    why: "Tomato is group 2 with fdc = 0.40 at 0.20 in/d, so frc = 1 − 0.40 = 0.60.",
    eq: "6.1", calc: "tab-6.1", fig: null, table: "6.1" },
  { id: "6-124", ch: 6, sec: "6.2", page: 109, type: "table", level: 2,
    q: "From Table 6.1, how does fdc for wheat change from a cool period (0.12 in/d) to a hot period (0.31 in/d)?",
    opts: ["From 0.70 to 0.38","From 0.80 to 0.45","From 0.58 to 0.28","It stays at 0.50"], a: 0,
    why: "Wheat is group 3: 0.70 at 0.12 in/d and 0.38 at 0.31 in/d. Hot weather nearly halves the allowable depletion.",
    eq: null, calc: "tab-6.1", fig: null, table: "6.1" },
  { id: "6-125", ch: 6, sec: "6.2", page: 109, type: "table", level: 3,
    q: "Alfalfa has TAW = 6.0 in, and the maximum ET is 0.28 in/d. Using Table 6.1, what is AD?",
    opts: ["3.3 in","3.0 in","2.6 in","1.4 in"], a: 2,
    why: "Alfalfa is group 3, fdc = 0.43 at 0.28 in/d. AD = 0.43 × 6.0 = 2.58, about 2.6 in. 3.0 in uses the default 0.50 and 3.3 in uses group 4.",
    eq: "6.4", calc: "tab-6.1", fig: null, table: "6.1" },
  { id: "6-126", ch: 6, sec: "6.3.1", page: 110, type: "table", level: 1,
    q: "From Table 6.2, what is the range of maximum effective rooting depth for corn?",
    opts: ["3.3 to 6.6 ft","1.3 to 2.6 ft","2.0 to 3.3 ft","5.0 to 8.3 ft"], a: 0,
    why: "Corn and maize are listed at 3.3 to 6.6 ft. 1.3 to 2.6 ft is beans or potatoes and 5.0 to 8.3 ft is dates.",
    eq: null, calc: "tab-6.2", fig: null, table: "6.2" },
  { id: "6-127", ch: 6, sec: "6.3.1", page: 110, type: "table", level: 1,
    q: "According to Table 6.2, which crop has the shallowest maximum effective rooting depth?",
    opts: ["Pineapple, 1.0 to 2.0 ft","Lettuce, 1.0 to 1.7 ft","Strawberries, 0.7 to 1.0 ft","Potatoes, 1.3 to 2.6 ft"], a: 2,
    why: "Strawberries are listed at 0.7 to 1.0 ft. Lettuce, celery and spinach are 1.0 to 1.7 ft.",
    eq: null, calc: "tab-6.2", fig: null, table: "6.2" },
  { id: "6-128", ch: 6, sec: "6.3.1", page: 112, type: "table", level: 1,
    q: "From Table 6.3, what root depth is assumed for corn at silking?",
    opts: ["3.0 ft","2.0 ft","2.5 ft","4.0 ft"], a: 0,
    why: "Corn is at 2.0 ft at 12 leaf, 2.5 ft at 16 leaf, 3.0 ft at silking, 3.5 ft at blister and 4.0 ft at beginning dent.",
    eq: null, calc: "tab-6.3", fig: null, table: "6.3" },
  { id: "6-129", ch: 6, sec: "6.3.1", page: 112, type: "table", level: 2,
    q: "From Table 6.3, what root depth is assumed for soybean at full bloom?",
    opts: ["3.0 ft","2.0 ft","2.5 ft","1.0 ft"], a: 2,
    why: "Soybean is 2.0 ft at early bloom, 2.5 ft at full bloom, and 3.0 ft at pod elongation, which is its maximum depth for irrigation management.",
    eq: null, calc: "tab-6.3", fig: null, table: "6.3" },
  { id: "6-130", ch: 6, sec: "6.3.1", page: 112, type: "table", level: 2,
    q: "From Table 6.3, what is the maximum root depth for irrigation management of dry beans, and at what stage is it reached?",
    opts: ["4.0 ft, at full seed fill","3.0 ft, at pod elongation","2.0 ft, at beginning pod fill","2.5 ft, at full seed fill"], a: 3,
    why: "Dry beans are marked (2.5) as their maximum depth, reached at full seed fill. 2.0 ft is beginning pod fill.",
    eq: null, calc: "tab-6.3", fig: null, table: "6.3" },
  { id: "6-131", ch: 6, sec: "6.4.1", page: 117, type: "table", level: 1,
    q: "From Table 6.4, what long-term water use rate applies to corn at silking?",
    opts: ["0.28 in/d","0.30 in/d","0.24 in/d","0.20 in/d"], a: 1,
    why: "Corn uses about 0.30 in/d at silking, 0.28 at early tassel, 0.24 at 12 leaf and milk, and 0.20 at beginning dent.",
    eq: null, calc: "tab-6.4", fig: null, table: "6.4" },
  { id: "6-132", ch: 6, sec: "6.4.1", page: 117, type: "table", level: 3,
    q: "Alfalfa was cut 5 days ago around July 1. Using Table 6.4 and its footnote, what forecast water use rate should you use?",
    opts: ["0.23 in/d","0.30 in/d","0.15 in/d","0.08 in/d"], a: 2,
    why: "Alfalfa uses 0.30 in/d on July 1. In the first 10 days after cutting multiply by 0.50, giving 0.15 in/d. 0.23 in/d uses the 0.75 factor for days 10 to 20.",
    eq: null, calc: "tab-6.4", fig: null, table: "6.4" },
  { id: "6-133", ch: 6, sec: "6.4.3", page: 121, type: "table", level: 3,
    q: "A tensiometer in fine sandy loam reads 40 cb and represents a 12-in layer. Using Table 6.5, what is the SWD in that layer?",
    opts: ["0.70 in","0.58 in","0.05 in","1.80 in"], a: 0,
    why: "Fine sandy loam at 40 cb is depleted 0.058 in/in. 0.058 × 12 = 0.70 in. 0.58 in is the table value times 10 instead of 12.",
    eq: null, calc: "tab-6.5", fig: null, table: "6.5" },
  { id: "6-134", ch: 6, sec: "6.4.3", page: 121, type: "table", level: 3,
    q: "In a sandy loam, sensors at 6, 18, and 30 in each represent 12 in and read 30, 50, and 20 cb. Using Table 6.5, what is the SWD of the 36-in root zone?",
    opts: ["0.13 in","1.2 in","1.8 in","1.5 in"], a: 3,
    why: "Sandy loam: 30 cb is 0.042, 50 cb is 0.058, 20 cb is 0.025 in/in. SWD = 12(0.042 + 0.058 + 0.025) = 1.50 in. 0.13 in forgets to multiply by layer thickness.",
    eq: null, calc: "tab-6.5", fig: null, table: "6.5" },
  { id: "6-135", ch: 6, sec: "6.4.3", page: 121, type: "table", level: 1,
    q: "From Table 6.6, what threshold soil water tension starts irrigation in a sandy loam?",
    opts: ["80 cb","25 cb","45 cb","35 cb"], a: 3,
    why: "Sandy loam is 35 cb. Loamy sand is 25 cb, fine sandy loam 45 cb, and silt loam and clay loam 80 cb.",
    eq: null, calc: "tab-6.6", fig: null, table: "6.6" },
  { id: "6-136", ch: 6, sec: "6.4.3", page: 121, type: "table", level: 3,
    q: "Table 6.6 lists 20 cb for fine sand but 80 cb for silt loam at the same fdc of 0.35. Why?",
    opts: ["Finer soils hold more water at a given tension, so 35% depletion is reached at a much higher tension","Silt loam crops are more drought tolerant","Fine sand sensors read high","Silt loam has a smaller AWC"], a: 0,
    why: "Release curves differ by texture. Coarse soils drain most of their available water at low tension, while silt loam still holds much of it at 80 cb.",
    eq: null, calc: "tab-6.6", fig: null, table: "6.6" },
  { id: "6-137", ch: 6, sec: "6.4", page: 114, type: "scenario", level: 3,
    q: "A grower probes his 3-ft corn root zone (AWC 0.15 in/in, fdc 0.50) and estimates fr = 0.60. Forecast ET is 0.27 in/d. He asks: \"How long before I have to water?\"",
    opts: ["About 2 d","About 8 d","About 4 d","Irrigate today"], a: 0,
    why: "TAW = 5.4 in, AD = 2.7 in, SWD = 0.40 × 5.4 = 2.16 in, and LD = (2.7 − 2.16) / 0.27 = 2 d. 8 d is SWD / ET, and 10 d would be AD / ET.",
    eq: "6.10", calc: "ld-ed-window", fig: null, table: null },
  { id: "6-138", ch: 6, sec: "6.4", page: 114, type: "scenario", level: 3,
    q: "A grower says: \"At my ending position the LD is 2 days, but the pivot needs 3 days to get there.\" What do you tell him?",
    opts: ["Wait 3 days and irrigate normally","That spot will be about 1 day late, so speed up the pivot with a lighter application or start sooner next time","It is fine because LD is only an estimate","Stop the pivot until it rains"], a: 1,
    why: "The book uses this case: irrigation will be 1 day late at that location. Faster speed (lighter depth) shortens the cycle, or the next cycle should start earlier.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-139", ch: 6, sec: "6.4.2", page: 120, type: "scenario", level: 1,
    q: "A grower on a 3-day schedule says: \"We got 0.8 inch of good rain yesterday and ET is about 0.2 inch a day.\" How long should he hold off?",
    opts: ["About 8 days","About 1.6 days","About 3 days","About 4 more days"], a: 3,
    why: "Delay = Pe / ET = 0.8 / 0.2 = 4 d, assuming he was not behind and all the rain was effective.",
    eq: "6.9", calc: "eq-6.9", fig: null, table: null },
  { id: "6-140", ch: 6, sec: "6.4", page: 115, type: "scenario", level: 2,
    q: "A Delaware grower asks: \"Should I fill my soil profile to field capacity every irrigation?\" What does the book's ED concept suggest?",
    opts: ["Yes, always fill it to field capacity","No, leave a rainfall allowance so rain right after irrigating can be stored","Yes, and add extra to leach","No, never apply more than 0.25 in"], a: 1,
    why: "In humid and semihumid regions, room for rain (ra) avoids deep percolation and makes more rain effective. That is built into ED = (ra + dep − SWD) / ETf.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-141", ch: 6, sec: "6.4.1", page: 117, type: "scenario", level: 1,
    q: "A grower wants to start a checkbook in spring but has no soil probe. How can he set the starting SWD?",
    opts: ["Assume SWD equals AD","Assume the soil is at wilting point","Start right after a soaking rain or thorough irrigation and assume the soil is near field capacity","Wait until the crop wilts"], a: 2,
    why: "The book suggests beginning after a wet period or thorough irrigation, when SWD is near zero, if soil water is not measured.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-142", ch: 6, sec: "6.4.1", page: 118, type: "scenario", level: 3,
    q: "A grower on fine sandy loam has a water table about 3 ft below the root zone. He asks whether to count it in his checkbook. Using Figure 6.10, what do you say?",
    opts: ["Yes, but only about 0.001 in/d","No, water tables never supply crops","No, upward flow only occurs in sand","Yes, fine sandy loam can supply roughly 0.2 in/d or more at that depth, a large share of ET"], a: 3,
    why: "The fine sandy loam curve starts near 0.24 in/d at about 3 ft. That is a substantial Uf term and ignoring it would over-irrigate.",
    eq: "6.18", calc: "eq-6.18-6.25", fig: "6.10", table: null },
  { id: "6-143", ch: 6, sec: "6.4.3", page: 121, type: "scenario", level: 1,
    q: "A grower's tensiometer in the middle of the root zone in a sandy loam reads 30 cb. Using Table 6.6, what do you advise?",
    opts: ["Irrigate immediately, it is past the threshold","It is close to the 35 cb threshold, so plan to irrigate soon","Wait until it reaches 80 cb","The soil is saturated"], a: 1,
    why: "The sandy loam threshold is 35 cb. At 30 cb the soil is near the trigger, so plan the irrigation. 80 cb is the silt loam and clay loam threshold.",
    eq: null, calc: "tab-6.6", fig: null, table: "6.6" },
  { id: "6-144", ch: 6, sec: "6.4.3", page: 120, type: "scenario", level: 1,
    q: "A grower installing sensors in a 3-ft root zone asks at what depths to put them. What do you tell him?",
    opts: ["Only at 6 in","12, 24, and 36 in","About 6, 18, and 30 in, one per foot of root zone","Only at 36 in"], a: 2,
    why: "Each sensor represents a 1-ft layer, so it sits in the middle of that layer. The whole root zone must be measured.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-145", ch: 6, sec: "6.4.3", page: 122, type: "scenario", level: 3,
    q: "A grower complains: \"My new probes read 0.38 at field capacity, but the lab says 0.30.\" How should he use the data?",
    opts: ["Use only the lab value with the raw readings","Throw out the probes","Subtract 0.08 from all lab values","Use the probe's own observed field capacity and track SWD = (θFC,obs − θv)Rd"], a: 3,
    why: "Managing SWD trends from each sensor's observed FC cancels much of the sensor offset and local soil variation (Singh et al., 2020).",
    eq: null, calc: "swd-fcobs", fig: null, table: null },
  { id: "6-146", ch: 6, sec: "6.4.3", page: 122, type: "scenario", level: 2,
    q: "A grower with a 130-ac pivot on fairly uniform soil asks how many places to monitor soil water. What is the book's guidance?",
    opts: ["Only the driest spot","One location near the pivot point","Every 10 ac","At least 4 locations, plus stress-prone areas if they are a significant part of the field"], a: 3,
    why: "The minimum is four locations in a large uniform area. Add sandy knobs or slopes only if they are a significant share. Pairing with checkbook accounting lowers the number needed.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-147", ch: 6, sec: "6.4.2", page: 120, type: "scenario", level: 3,
    q: "A grower irrigates weekly. Last week ET totaled 1.6 in and effective rain was 0.5 in. His pivot ELQ is 85%. How much gross water should he apply?",
    opts: ["About 1.1 in","About 1.3 in","About 0.9 in","About 2.5 in"], a: 1,
    why: "Effective need = 1.6 − 0.5 = 1.1 in (Eq. 6.26). Gross = 1.1 / 0.85 = 1.29, about 1.3 in. 0.9 in multiplies by ELQ instead of dividing.",
    eq: "6.26", calc: "eq-6.26", fig: null, table: null },
  { id: "6-148", ch: 6, sec: "6.5.2", page: 124, type: "scenario", level: 2,
    q: "A grower's handheld infrared thermometer shows his canopy several degrees warmer than the air at midday on a clear day. What do you tell him?",
    opts: ["Warm canopies mean the crop is healthy","It suggests water stress, but check vapor pressure deficit, wind, clouds, and bare soil in the view before acting","The thermometer must be broken","It means the soil is at field capacity"], a: 1,
    why: "Well-watered canopies are usually cooler than air. Interpreting DT needs VPD and conditions such as wind and clouds, and bare soil in the field of view raises readings.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-149", ch: 6, sec: "6.5.1", page: 123, type: "scenario", level: 2,
    q: "A corn grower wants to use a pressure chamber to time irrigations. What should he know?",
    opts: ["One leaf per field is enough","It gives a forecast of the latest date","Any time of day works the same","Thresholds near −12 to −12.5 bars midafternoon have been reported, but sampling is slow, time-limited, and needs many leaves"], a: 3,
    why: "Leaf water potential is a direct plant measure, but it needs crop-specific thresholds, a narrow midday window, and many samples, and it does not predict ahead.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-150", ch: 6, sec: "6.5.3", page: 124, type: "scenario", level: 1,
    q: "A golf superintendent sees bluegrass fairways turning blue-green in the afternoon. What does it mean?",
    opts: ["It is a fertilizer burn","The turf is over-watered","The turf is under water stress and needs water","It is normal dormancy"], a: 2,
    why: "Stressed plants darken, and bluegrass turns blue-green under water stress. Visual cues are late signals, so soil water or ET scheduling should catch it sooner.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-151", ch: 6, sec: "6.6", page: 125, type: "scenario", level: 2,
    q: "A pivot covers sandy soil on one side and clay loam on the other, and the field starts the season at field capacity. With VRI, which side should he irrigate first?",
    opts: ["The sandy side, because its lower AWC reaches AD first","The clay loam side, because it holds more","Both equally","Neither until the clay loam is dry"], a: 0,
    why: "Lower AWC means smaller TAW and AD, so the sand hits AD first. Holding water off the clay loam mines its stored water and can save pumping.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-152", ch: 6, sec: "6.6", page: 125, type: "scenario", level: 1,
    q: "A grower wants to chemigate but a creek crosses his pivot field. What VRI feature helps?",
    opts: ["An avoidance zone that shuts off application over the creek","A higher pivot speed over the field","An end gun over the creek","A larger nozzle package"], a: 0,
    why: "An avoidance zone turns off water and chemical over waterways or other noncropped areas, so chemigation can continue legally on the rest of the field.",
    eq: null, calc: null, fig: "6.16", table: null },
  { id: "6-153", ch: 6, sec: "6.2", page: 108, type: "scenario", level: 3,
    q: "A grower with onions and corn on the same soil asks if he can use the same irrigation trigger for both. What do you say?",
    opts: ["Yes, onions can deplete more","Yes, all crops use 0.50","No, onions are far more sensitive, about 0.23 depletion versus about 0.50 for corn at the same ET","No, corn is more sensitive than onions"], a: 2,
    why: "At about 0.28 in/d, Table 6.1 gives fdc 0.23 for onions (group 1) and 0.50 for corn (group 4). The onions must be watered at a much smaller deficit.",
    eq: null, calc: "tab-6.1", fig: null, table: "6.1" },
  { id: "6-154", ch: 6, sec: "6.3.1", page: 110, type: "scenario", level: 2,
    q: "A grower's corn is at 6 leaves with roots about 1 ft deep. He plans to count the full 3-ft soil profile in his checkbook. What do you tell him?",
    opts: ["Use the full 3 ft, roots will get there anyway","Use the current root depth, which gives a smaller TAW and AD, so irrigations should be lighter and more frequent","Use 5 ft to be safe","Root depth does not matter early"], a: 1,
    why: "TAW = Rd × AWC uses the actual root zone. Counting soil the roots cannot reach overstates AD and risks stress. Eq. 6.6 and Table 6.3 estimate depth by stage.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-155", ch: 6, sec: "6.4", page: 113, type: "scenario", level: 3,
    q: "A grower irrigates 1 in every 2 days on deep silt loam, but his checkbook shows SWD is only 0.3 in at each irrigation. What do you tell him?",
    opts: ["Keep going, silt loam stores it all","Infiltration well above SWD is going to deep percolation, so wait until at least the ED","Irrigate daily instead","Increase the depth to 1.5 in"], a: 1,
    why: "Infiltration should not exceed SWD. With SWD 0.3 in, most of the inch percolates. Waiting until ED leaves room for the irrigation and a rain allowance.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-156", ch: 6, sec: "6.4.1", page: 119, type: "scenario", level: 2,
    q: "In late August a grower in a semiarid area asks whether to keep his corn profile full until maturity. What does the book suggest?",
    opts: ["Fill the profile to field capacity before harvest","Let soil water deplete to low but safe levels by maturity so off-season precipitation can be stored","Stop irrigating at silking","Irrigate after harvest to store water"], a: 1,
    why: "Programmed soil moisture depletion (Figure 6.12) replaces only part of ET late in the season, leaving room for off-season precipitation and reducing next year's irrigation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-157", ch: 6, sec: "6.4.3", page: 121, type: "scenario", level: 3,
    q: "A grower uses a threshold tension to decide when to irrigate. He asks how much to apply. What is the honest answer?",
    opts: ["Apply the AD every time","Always apply 1 in","Apply until the tensiometer reads 0","The threshold does not tell you, so convert readings to SWD with a release curve (such as Table 6.5) or use a checkbook"], a: 3,
    why: "The threshold method tells when but not how much the soil can hold. Converting tension to SWD per layer gives the depth to refill without deep percolation.",
    eq: null, calc: null, fig: null, table: "6.5" },
  { id: "6-158", ch: 6, sec: "6.4", page: 115, type: "scenario", level: 3,
    q: "At the start position ED is 1 d and LD is 4 d. The pivot takes 3 d to complete a circle, and conditions are similar around the field. When should the grower start?",
    opts: ["About 1 d from now, so the end of the circle is reached by its LD","Today, to be safe","In 4 d, at the LD","In 6 d, after the cycle"], a: 0,
    why: "Starting at the ED avoids deep percolation at the start position. Starting at day 1 with a 3-d cycle reaches the last position by about day 4, its LD. Waiting until day 4 would leave the far side 3 d late.",
    eq: null, calc: null, fig: null, table: null },
  { id: "6-159", ch: 6, sec: "6.4.1", page: 117, type: "scenario", level: 2,
    q: "An alfalfa grower just cut his field. How should he adjust forecast ET for the next 10 days?",
    opts: ["Double the rate to account for drying","Keep the full rate, cutting does not matter","Set ET to zero until regrowth","Multiply the long-term water use rate by 0.50, then by 0.75 from day 10 to 20"], a: 3,
    why: "The footnote to Table 6.4 says alfalfa rates should be multiplied by 0.50 for the first 10 days after cutting and by 0.75 from the 10th to 20th day.",
    eq: null, calc: "tab-6.4", fig: null, table: "6.4" },
  { id: "6-160", ch: 6, sec: "6.4.3", page: 122, type: "scenario", level: 2,
    q: "Feel and appearance checks in a lettuce field show fr = 0.60 at one location and 0.80 at another. Which location should set the irrigation timing?",
    opts: ["Neither, use the calendar","The wetter location (fr = 0.80)","The average of the two, fr = 0.70","The drier location (fr = 0.60), because it reaches its latest date first"], a: 3,
    why: "In Example 6.7 the drier spot had LD = 1 d while the wetter spot had LD = 3 d. Irrigation must arrive before AD is exceeded at the most depleted significant location.",
    eq: null, calc: null, fig: null, table: null }
]);
